export async function openEffectLiveEditor(document,{read,setParameter,error}){
 const dialog=document.createElement('dialog');dialog.className='effect-live-dialog';dialog.dataset.effectLiveDetails='';
 const heading=document.createElement('header'),title=document.createElement('strong'),close=document.createElement('button');title.textContent='활성 효과';close.textContent='닫기';close.onclick=()=>dialog.close();heading.append(title,close);const body=document.createElement('div');body.className='effect-live-body';dialog.append(heading,body);document.body.append(dialog);dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();let serial=0,stamp='',offsetNow=0,timer;dialog.addEventListener('close',()=>clearInterval(timer),{once:true});
 const node=(tag,text)=>{const e=document.createElement(tag);e.textContent=text;return e;};
 async function render(offset=0){offsetNow=offset;const ticket=++serial;try{const page=await read(offset);if(!dialog.isConnected||ticket!==serial)return;if(!page.ready)throw Error('활성 효과가 종료됐어요.');const nextStamp=JSON.stringify([offset,page.total,page.items]);if(nextStamp===stamp)return;stamp=nextStamp;title.textContent=page.asset.split('/').at(-1).replace('.hbeffect.json','');const content=document.createDocumentFragment(),table=document.createElement('table'),thead=node('thead',''),row=document.createElement('tr');for(const text of ['속성','계산 입력','캡처/인자','계수','결과'])row.append(node('th',text));thead.append(row);table.append(thead);const tbody=document.createElement('tbody');
   for(const item of page.items){const tr=document.createElement('tr'),input=item.magnitudeSource;for(const text of [item.attribute,input?.type==='attribute'?(input.owner==='source'?'출처':'대상')+' · '+input.attribute+' · '+(input.basis==='base'?'기본':'현재')+' · '+(input.snapshot===false?'실시간':'고정'):input?.type==='parameter'?input.name:'상수',input?String(item.input):'—',String(item.baseMagnitude),String(item.magnitude)])tr.append(node('td',text));tbody.append(tr);}table.append(tbody);content.append(table);
   const names=new Set();for(const item of page.items){const source=item.magnitudeSource;if(source?.type!=='parameter'||names.has(source.name))continue;names.add(source.name);const label=node('label',source.name),input=node('input','');input.type='number';input.step='any';input.value=item.input;input.dataset.effectParameter=source.name;input.setAttribute('aria-label',source.name);label.append(input);input.onchange=async()=>{input.disabled=true;try{await setParameter(source.name,Number(input.value));await render(offset);}catch(e){error(e.message);if(input.isConnected){input.value=item.input;input.disabled=false;}}};content.append(label);}
   if(page.total>page.items.length){const nav=node('footer',''),previous=node('button','이전'),next=node('button','다음');previous.disabled=!offset;previous.onclick=()=>render(Math.max(0,offset-64));next.disabled=page.nextOffset===null;next.onclick=()=>render(page.nextOffset);nav.append(previous,node('output',(offset+1)+'–'+Math.min(page.total,offset+page.items.length)+' / '+page.total),next);content.append(nav);}body.replaceChildren(content);
  }catch(e){clearInterval(timer);if(dialog.isConnected){body.replaceChildren(node('p',e.message));error(e.message);}}
 }
 await render();if(dialog.isConnected&&stamp)timer=setInterval(()=>{if(!document.activeElement?.matches('[data-effect-parameter]'))void render(offsetNow);},250);return dialog;
}
